-- Tinh TongTien = tien dien (chia theo ty le thoi gian trong tung khung) + phi do xe
UPDATE HOA_DON h
JOIN (
  SELECT x.MaPhien,
         ROUND( x.kwh * SUM(x.GiayTrongKhung * x.DonGia_kWh)
                      / TIMESTAMPDIFF(SECOND, x.s, x.e)
              + TIMESTAMPDIFF(SECOND, x.s, x.e) / 3600 * @phi_do_xe_gio, 0) AS TongTienTinh
  FROM (
    SELECT p.MaPhien, p.TG_BatDauTT AS s, p.TG_KetThucTT AS e,
           p.DienNangTieuThu_kWh AS kwh, w.DonGia_kWh,
           GREATEST(0, TIMESTAMPDIFF(SECOND,
               GREATEST(p.TG_BatDauTT, TIMESTAMP(DATE(p.TG_BatDauTT), w.KhungGioBatDau)),
               LEAST(p.TG_KetThucTT,   TIMESTAMP(DATE(p.TG_BatDauTT), w.KhungGioKetThuc)))) AS GiayTrongKhung
    FROM   PHIEN_SAC p
    JOIN   DAT_CHO  d ON d.MaDatCho = p.MaDatCho
    JOIN   CONG_SAC c ON c.MaCong   = d.MaCong
    JOIN   BANG_GIA w ON w.MaTram   = c.MaTram
                     AND w.LoaiNgay = CASE
                           WHEN DATE(p.TG_BatDauTT) IN ('2026-09-02') THEN 'LeTet'
                           WHEN DAYOFWEEK(p.TG_BatDauTT) IN (1,7)     THEN 'CuoiTuan'
                           ELSE 'Thuong' END
    WHERE  p.TG_KetThucTT IS NOT NULL
  ) x
  GROUP BY x.MaPhien, x.s, x.e, x.kwh
) t ON t.MaPhien = h.MaPhien
SET h.TongTien = t.TongTienTinh;

/* ------------------------------------------- BAO TRI CONG (BR27) - lam sau cung */
UPDATE CONG_SAC SET TrangThai = 'Maintenance' WHERE MaCong = 9;
UPDATE CONG_SAC SET TrangThai = 'Inactive'    WHERE MaCong = 12;

