-- UNION ALL SELECT 'TRAM_SAC', COUNT(*) FROM TRAM_SAC UNION ALL SELECT 'CONG_SAC', COUNT(*) FROM CONG_SAC
-- UNION ALL SELECT 'BANG_GIA', COUNT(*) FROM BANG_GIA UNION ALL SELECT 'DAT_CHO', COUNT(*) FROM DAT_CHO
-- UNION ALL SELECT 'PHIEN_SAC', COUNT(*) FROM PHIEN_SAC UNION ALL SELECT 'HOA_DON', COUNT(*) FROM HOA_DON
-- UNION ALL SELECT 'AUDIT_LOG', COUNT(*) FROM AUDIT_LOG;
-- Ky vong: 1150 / 1501 / 3 / 12 / 21 / 3295 / 3016 / 3014 / (21 bang gia + 4 doi trang thai cong = 25)
-- Trang thai ky vong sau khi nap: DAT_CHO 15,16 = Active; CONG_SAC 3,7 = Occupied; 9 = Maintenance; 12 = Inactive.
